import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture as textureNode } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();

  const geometries = [];
  const materials = [];
  const textures = [];
  const timelines = [];

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    geometries.forEach(g => g.dispose());
    materials.forEach(m => m.dispose());
    textures.forEach(t => t.dispose());
    timelines.forEach(tl => tl.kill());
  };

  // Load image texture
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);
  textures.push(imageTexture);

  // Determine plane dimensions from atlas region
  const atlasWidth = config.atlasRegion?.width ?? 512;
  const atlasHeight = config.atlasRegion?.height ?? 320;
  const aspectRatio = atlasWidth / atlasHeight;

  const planeGeometry = new THREE.PlaneGeometry(aspectRatio, 1);
  geometries.push(planeGeometry);

  // Create material with texture node
  const planeMaterial = new MeshBasicNodeMaterial();
  planeMaterial.colorNode = textureNode(imageTexture);
  materials.push(planeMaterial);

  // Create and position image mesh
  const imageMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  imageMesh.position.set(0, 1.85, 0);
  root.add(imageMesh);

  // Render text content
  if (config.textContent && config.textContent.length > 0 && ctx.fontAtlas) {
    const textItem = config.textContent[0];
    const textString = typeof textItem === 'string' ? textItem : (textItem.text ?? '');

    if (textString) {
      const inkColor = config.colors?.ink ?? '#16161d';

      const textMesh = ctx.fontAtlas.createTextMesh(textString, {
        font: 'display',
        size: 0.34,
        weight: 400,
        color: new THREE.Color(inkColor),
        align: 'center'
      });

      if (textMesh) {
        textMesh.position.z = 0.01;
        root.add(textMesh);
      }
    }
  }

  return root;
}
